import { API_HOST } from "@/lib/api";

export const revalidate = 3600;

function escapeXml(unsafe: string | null | undefined): string {
  if (!unsafe) return "";
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

interface FeedArticle {
  id: string;
  title: string;
  summary?: string | null;
  slug?: string | null;
  publishedAt: string;
  category?: string | null;
}

function generateRssXml(articles: FeedArticle[]): string {
  const buildDate = new Date().toUTCString();
  const siteUrl = "https://www.trayago.in";

  const itemsXml = articles
    .filter((a) => a.title && a.title.trim().length > 0 && a.publishedAt)
    .map((a) => {
      const slugOrId = (a.slug && typeof a.slug === "string" && a.slug.trim().length > 0)
        ? a.slug.trim().toLowerCase()
        : (a.id && typeof a.id === "string")
          ? a.id.trim()
          : "";
      const articleUrl = `${siteUrl}/news/${encodeURIComponent(slugOrId)}`;
      const pubDate = !isNaN(new Date(a.publishedAt).getTime())
        ? new Date(a.publishedAt).toUTCString()
        : buildDate;

      const categoryTag =
        a.category && a.category.trim()
          ? `\n      <category>${escapeXml(a.category.trim())}</category>`
          : "";

      return `    <item>
      <title>${escapeXml(a.title.trim())}</title>
      <link>${escapeXml(articleUrl)}</link>
      <guid isPermaLink="true">${escapeXml(articleUrl)}</guid>
      <pubDate>${pubDate}</pubDate>
      <description>${escapeXml(a.summary?.trim() || "")}</description>${categoryTag}
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>Trayago Railway News &amp; Updates</title>
    <link>${siteUrl}/news</link>
    <description>Verified Indian Railways news, IRCTC alerts, train delays, cancellations, and passenger travel advisories curated by Trayago.</description>
    <language>en-in</language>
    <lastBuildDate>${buildDate}</lastBuildDate>
    <atom:link href="${siteUrl}/news/feed.xml" rel="self" type="application/rss+xml"/>
${itemsXml}
  </channel>
</rss>`.trim();
}

export async function GET() {
  let articles: FeedArticle[] = [];

  try {
    const res = await fetch(`${API_HOST}/api/news?limit=30`, {
      cache: "no-store",
    }).catch(() => null);

    if (res && res.ok) {
      const json = await res.json();
      if (json.success && Array.isArray(json.data)) {
        articles = json.data;
      }
    }
  } catch (err) {
    console.error("[RSS Feed] Error fetching published news:", err);
  }

  const xml = generateRssXml(articles);

  return new Response(xml, {
    status: 200,
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=1800, s-maxage=3600",
    },
  });
}
